// =====================================================
// INA226
// =====================================================

#define SDA_PIN 21
#define SCL_PIN 22
#define INA226_ADDRESS 0x40

const float SHUNT_OHMS = 0.00075;
const float INA226_SHUNT_LSB_V = 0.0000025;

// =====================================================
// BATTERY VOLTAGE
// =====================================================

// D34 = GPIO34
#define BATTERY_VOLTAGE_PIN 34

// Based on your measured:
// Battery = 13.25 V
// Divider output = 2.63 V

const float VOLTAGE_DIVIDER_RATIO = 5.038;

// Don't calibrate this yet.
// First we stabilize the reading.
const float VOLTAGE_CALIBRATION = 1.000;

// =====================================================
// SERVER
// =====================================================

WebServer server(80);

// =====================================================
// LIGHTING STATE
// =====================================================

uint8_t currentR = 128;
uint8_t currentG = 0;
uint8_t currentB = 255;

