// =====================================================
// BATTERY MONITOR STATE
// =====================================================

float rawBatteryVoltage      = 0.0;
float batteryVoltage         = 0.0;

float shuntVoltage_mV        = 0.0;
float current_A              = 0.0;
float filteredCurrent_A      = 0.0;

float power_W                = 0.0;
float peakCurrent_A          = 0.0;

float sessionAh              = 0.0;
float dischargedAh           = 0.0;
float chargedAh              = 0.0;

// =====================================================
// TIMING
// =====================================================

const unsigned long SAMPLE_INTERVAL_MS = 100;

unsigned long lastSampleMillis = 0;
unsigned long sessionStartMillis = 0;

// =====================================================
// INA226 REGISTER READ
// =====================================================

bool readINA226Register(
  uint8_t reg,
  int16_t &value
) {

  Wire.beginTransmission(INA226_ADDRESS);
  Wire.write(reg);

  if (Wire.endTransmission(false) != 0) {
    return false;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (Wire.available() < 2) {
    return false;
  }

  uint16_t raw =
    ((uint16_t)Wire.read() << 8) |
    Wire.read();

  value = (int16_t)raw;

  return true;
}

// =====================================================
// SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(float &millivolts) {

  int16_t raw;

  if (!readINA226Register(0x01, raw)) {
    return false;
  }

  float volts =
    raw * INA226_SHUNT_LSB_V;

  millivolts =
    volts * 1000.0;

  return true;
}

// =====================================================
// SORT FUNCTION
// =====================================================

void sortValues(
  uint32_t values[],
  int count
) {

  for (int i = 0; i < count - 1; i++) {

    for (int j = i + 1; j < count; j++) {

      if (values[j] < values[i]) {

        uint32_t temp = values[i];

        values[i] = values[j];
        values[j] = temp;
      }
    }
  }
}

// =====================================================
// BATTERY VOLTAGE READING
// =====================================================

float readBatteryVoltage() {

  // Take 64 ADC measurements.
  const int SAMPLE_COUNT = 64;

  uint32_t samples[SAMPLE_COUNT];

  for (int i = 0; i < SAMPLE_COUNT; i++) {

    samples[i] =
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(150);
  }

  // Sort from lowest to highest.
  sortValues(
    samples,
    SAMPLE_COUNT
  );

  // Throw away the lowest 12
  // and highest 12 measurements.
  //
  // This removes ADC spikes/outliers.

  const int FIRST_SAMPLE = 12;
  const int LAST_SAMPLE  = 52;

  uint32_t total = 0;
  int usedSamples = 0;

  for (
    int i = FIRST_SAMPLE;
    i < LAST_SAMPLE;
    i++
  ) {

    total += samples[i];
    usedSamples++;
  }

  float sensorMillivolts =
    total /
    (float)usedSamples;

  float sensorVolts =
    sensorMillivolts /
    1000.0;

  float calculatedVoltage =
    sensorVolts *
    VOLTAGE_DIVIDER_RATIO *
    VOLTAGE_CALIBRATION;

  return calculatedVoltage;
}

// =====================================================
// UPDATE BATTERY MONITOR
// =====================================================

void updateBatteryMonitor() {

  unsigned long now = millis();

  if (
    now - lastSampleMillis <
    SAMPLE_INTERVAL_MS
  ) {

    return;
  }

  unsigned long elapsedMs =
    now - lastSampleMillis;

  lastSampleMillis = now;

  // ===================================================
  // BATTERY VOLTAGE
  // ===================================================

  rawBatteryVoltage =
    readBatteryVoltage();

  // Initialize filter on first reading.
  if (batteryVoltage == 0.0) {

    batteryVoltage =
      rawBatteryVoltage;
  }

  else {

    // Slow low-pass filter.
    //
    // 10% new measurement
    // 90% previous display value

    const float VOLTAGE_ALPHA = 0.10;

    batteryVoltage =
      (VOLTAGE_ALPHA *
       rawBatteryVoltage)
      +
      ((1.0 - VOLTAGE_ALPHA) *
       batteryVoltage);
  }

  // ===================================================
  // CURRENT
  // ===================================================

  float newShunt_mV;

  if (
    readShuntVoltage(
      newShunt_mV
    )
  ) {

    shuntVoltage_mV =
      newShunt_mV;

    float shuntVoltage_V =
      shuntVoltage_mV /
      1000.0;

    current_A =
      shuntVoltage_V /
      SHUNT_OHMS;

    // Zero deadband
    if (
      current_A > -0.01 &&
      current_A < 0.01
    ) {

      current_A = 0.0;
    }

    // Smooth dashboard current
    const float CURRENT_ALPHA = 0.25;

    filteredCurrent_A =
      (CURRENT_ALPHA *
       current_A)
      +
      ((1.0 - CURRENT_ALPHA) *
       filteredCurrent_A);

    // =================================================
    // PEAK CURRENT
    // =================================================

    float absoluteCurrent =
      fabs(current_A);

    if (
      absoluteCurrent >
      peakCurrent_A
    ) {

      peakCurrent_A =
        absoluteCurrent;
    }

    // =================================================
    // AMP-HOURS
    // =================================================

    float elapsedHours =
      elapsedMs /
      3600000.0;

    sessionAh +=
      current_A *
      elapsedHours;

    // For now, positive current = discharge
    if (current_A > 0) {

      dischargedAh +=
        current_A *
        elapsedHours;
    }

    else if (current_A < 0) {

      chargedAh +=
        (-current_A) *
        elapsedHours;
    }
  }

  // ===================================================
  // POWER
  // ===================================================

  power_W =
    batteryVoltage *
    filteredCurrent_A;
}

// =====================================================
// RESET SESSION
// =====================================================

void resetSession() {

  peakCurrent_A = 0.0;

  sessionAh = 0.0;
  dischargedAh = 0.0;
  chargedAh = 0.0;

  sessionStartMillis =
    millis();
}

// =====================================================
// RUNTIME
// =====================================================

String formatRuntime() {

  unsigned long seconds =
    (millis() -
     sessionStartMillis) /
    1000;

  unsigned long hours =
    seconds / 3600;

  unsigned long minutes =
    (seconds % 3600) / 60;

  seconds =
    seconds % 60;

  char buffer[20];

  snprintf(
    buffer,
    sizeof(buffer),
    "%02lu:%02lu:%02lu",
    hours,
    minutes,
    seconds
  );

  return String(buffer);
}

// =====================================================
// LIGHTING
// =====================================================

void showCurrentColor() {

  if (!lightsOn) {

    strip.clear();
    strip.show();

    return;
  }

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );
  }

  strip.show();
}

void setColor(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentR = r;
  currentG = g;
  currentB = b;

  lightsOn = true;

  showCurrentColor();
}

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303,
    "text/plain",
    ""
  );
}

