// =====================================================
// WEB ROUTES
// =====================================================

void setupWebServer() {

  server.on(
    "/",
    HTTP_GET,
    []() {

      server.send(
        200,
        "text/html",
        buildPage()
      );
    }
  );

  server.on(
    "/reset",
    HTTP_GET,
    []() {

      resetSession();
      returnHome();
    }
  );

  server.on(
    "/on",
    HTTP_GET,
    []() {

      lightsOn = true;
      showCurrentColor();
      returnHome();
    }
  );

  server.on(
    "/off",
    HTTP_GET,
    []() {

      lightsOn = false;

      strip.clear();
      strip.show();

      returnHome();
    }
  );

  server.on(
    "/red",
    HTTP_GET,
    []() {

      setColor(255, 0, 0);
      returnHome();
    }
  );

  server.on(
    "/green",
    HTTP_GET,
    []() {

      setColor(0, 255, 0);
      returnHome();
    }
  );

  server.on(
    "/blue",
    HTTP_GET,
    []() {

      setColor(0, 0, 255);
      returnHome();
    }
  );

  server.on(
    "/purple",
    HTTP_GET,
    []() {

      setColor(128, 0, 255);
      returnHome();
    }
  );

  server.on(
    "/white",
    HTTP_GET,
    []() {

      setColor(255, 255, 255);
      returnHome();
    }
  );

  // Firmware page

  server.on(
    "/updatepage",
    HTTP_GET,
    []() {

      server.send(
        200,
        "text/html",
        updatePage
      );
    }
  );

  // OTA upload

  server.on(
    "/update",
    HTTP_POST,

    []() {

      bool success =
        !Update.hasError();

      server.send(
        success ? 200 : 500,
        "text/plain",
        success
          ? "UPDATE SUCCESSFUL - REBOOTING"
          : "UPDATE FAILED"
      );

      delay(1000);

      if (success) {
        ESP.restart();
      }
    },

    []() {

      HTTPUpload& upload =
        server.upload();

      if (
        upload.status ==
        UPLOAD_FILE_START
      ) {

        if (
          !Update.begin(
            UPDATE_SIZE_UNKNOWN
          )
        ) {

          Update.printError(
            Serial
          );
        }
      }

      else if (
        upload.status ==
        UPLOAD_FILE_WRITE
      ) {

        if (
          Update.write(
            upload.buf,
            upload.currentSize
          )
          !=
          upload.currentSize
        ) {

          Update.printError(
            Serial
          );
        }
      }

      else if (
        upload.status ==
        UPLOAD_FILE_END
      ) {

        if (!Update.end(true)) {

          Update.printError(
            Serial
          );
        }
      }
    }
  );

  server.begin();
}

// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  delay(500);

  // LEDs

  strip.begin();

  strip.setBrightness(
    brightness
  );

  strip.clear();
  strip.show();

  // Battery ADC

  pinMode(
    BATTERY_VOLTAGE_PIN,
    INPUT
  );

  analogReadResolution(12);

  // INA226

  Wire.begin(
    SDA_PIN,
    SCL_PIN
  );

  // Wi-Fi

  WiFi.mode(WIFI_STA);

  WiFi.config(
    local_IP,
    gateway,
    subnet
  );

  WiFi.begin(
    ssid,
    password
  );

  while (
    WiFi.status() !=
    WL_CONNECTED
  ) {

    delay(500);
  }

  // Session

  sessionStartMillis =
    millis();

  lastSampleMillis =
    millis();

  // Server

  setupWebServer();

  // Purple startup

  setColor(
    128,
    0,
    255
  );
}

// =====================================================
// LOOP
// =====================================================

void loop() {

  updateBatteryMonitor();

  server.handleClient();
}
